class DeleteSuccessMessageMixinTests(SimpleTestCase):
    def setUp(self):
        self.factory = RequestFactory()

    @patch('django.contrib.messages.success')
    def test_delete_success_message(self, mock_success):
        request = self.factory.post('/')

        mock_object = MagicMock()
        mock_object.__dict__ = {'name': 'Test Object'}

        class TestDeleteView(DeleteSuccessMessageMixin, DeleteView):
            success_message = 'Object %(name)s deleted'
            def get_object(self):
                return mock_object
            def get_success_url(self):
                return '/'

        view = TestDeleteView()
        response = view.delete(request)

        self.assertIsInstance(response, HttpResponseRedirect)
        mock_success.assert_called_once_with(request, 'Object Test Object deleted')

    @patch('django.contrib.messages.success')
    def test_no_delete_success_message(self, mock_success):
        request = self.factory.post('/')

        mock_object = MagicMock()
        mock_object.__dict__ = {'name': 'Test Object'}

        class TestDeleteView(DeleteSuccessMessageMixin, DeleteView):
            success_message = ''
            def get_object(self):
                return mock_object
            def get_success_url(self):
                return '/'

        view = TestDeleteView()
        response = view.delete(request)

        self.assertIsInstance(response, HttpResponseRedirect)
        mock_success.assert_not_called()

if __name__ == '__main__':
    import unittest
    unittest.main()
