        pickled = dumps(match)
        loads(pickled)
        print("CBV pickling successful!")
    except Exception as e:
        print(f"CBV pickling failed: {e}")
        raise e

if __name__ == "__main__":
    test_pickle_fbv()
    test_pickle_cbv()
